    /// <summary>Decodes g10v2, BinaryOutputWithFlags.</summary>
    private static BinaryOutputStatus ParseG10V2(ReadOnlySpan<byte> buf, Context ctx)
    {
        var flags = new Flags(buf[0]);
        var time = Timestamp.NoTime();
        return new BinaryOutputStatus((buf[0] & 0x80) != 0, flags, time);
    }

    /// <summary>Encodes g10v2, BinaryOutputWithFlags.</summary>
    private static void WriteG10V2(List<byte> dst, BinaryOutputStatus v, Context ctx)
    {
        var flags = v.Flags.Clear(Flags.StateBit);
        if (v.Value)
        {
            flags = flags.Set(Flags.StateBit);
        }

        dst.Add(flags.Value);

        _ = ctx;
    }

    /// <summary>Decodes g11v1, BinaryOutputEventNoTime.</summary>
