        var time = new Timestamp
        {
            Time = Dnp3Time.FromDnp3(ObjectConvert.ReadTime48(buf.Slice(1, 6))),
            Quality = ctx.TimeQuality(),
        };
        return new BinaryOutputStatus((buf[0] & 0x80) != 0, flags, time);
    }

    /// <summary>Encodes g11v2, BinaryOutputEventAbsTime.</summary>
    private static void WriteG11V2(List<byte> dst, BinaryOutputStatus v, Context ctx)
    {
        var flags = v.Flags.Clear(Flags.StateBit);
